c(){ curl -sSLG --compressed -A "Mozilla/5.0" "$@"; }; [ -n "$F" ] || { printf "Nom de ce fournisseur : "; read -r F; }; [ -n "$U" ] || { printf "Adresse du serveur (ex. http://monserveur.com:8080) : "; read -r U; }; [ -n "$N" ] || { printf "Nom d'utilisateur : "; read -r N; }; printf "Mot de passe de %s chez %s (il ne s'affiche pas quand tu tapes) : " "$N" "$F"; read -rs P; echo; case "$U" in http*) ;; *) U="http://$U";; esac; U="${U%%/get.php*}"; U="${U%%/player_api.php*}"; U="${U%/}"; MS=$(c "$U/player_api.php" --data-urlencode "username=$N" --data-urlencode "password=$P" -o /dev/null -w "%{time_total}"); R=$(c "$U/player_api.php" --data-urlencode "username=$N" --data-urlencode "password=$P"); case "$R" in *'"auth":1'*|*'"auth": 1'*|*'"auth":"1"'*) echo "✓ Connexion acceptée";; *) echo "⚠ Le serveur refuse la connexion ou répond autre chose. Début de la réponse :"; echo "${R:0:200}";; esac; D=~/Desktop/prisme-"${F// /-}"; mkdir -p "$D" && cd "$D" && printf '%s' "$R" | MS="$MS" HOSTU="$U" perl -MJSON::PP -0777 -e 'my $j = eval { JSON::PP->new->utf8->decode(<STDIN>) } || {}; delete $j->{user_info}{password} if ref $j->{user_info} eq "HASH"; $j->{ms} = int(($ENV{MS} || 0) * 1000); $j->{at} = time; $j->{host} = $ENV{HOSTU}; print JSON::PP->new->utf8->canonical->encode($j)' > compte.json; echo "✓ compte : $(head -c 120 compte.json)"; for a in get_live_categories get_live_streams get_vod_categories get_vod_streams get_series_categories get_series; do c "$U/player_api.php" --data-urlencode "username=$N" --data-urlencode "password=$P" --data-urlencode "action=$a" -o "$a.json"; echo "✓ $a : $(wc -c < "$a.json" | tr -d ' ') octets, début : $(head -c 60 "$a.json")"; done; c "$U/xmltv.php" --data-urlencode "username=$N" --data-urlencode "password=$P" -o xmltv.xml; echo "✓ guide : $(wc -c < xmltv.xml | tr -d ' ') octets"; echo "… fiches des 400 films les plus récents chez ton fournisseur (résumé, casting, durée)"; mkdir -p vi; perl -MJSON::PP -0777 -e 'my $l = eval { JSON::PP->new->utf8->decode(<STDIN>) } || []; my @v = grep { ref $_ eq "HASH" && ($_->{name} // "") !~ /adult|xxx|porn|\+ ?18|18 ?\+/i } @$l; @v = sort { ($b->{added} || 0) <=> ($a->{added} || 0) } @v; print "$_->{stream_id}\n" for grep { $_->{stream_id} } @v[0 .. ($#v < 399 ? $#v : 399)]' < get_vod_streams.json > vi/ids.txt; export U N P; xargs -P 6 -I{} sh -c 'curl -sSLG --compressed -A "Mozilla/5.0" -m 20 "$U/player_api.php" --data-urlencode "username=$N" --data-urlencode "password=$P" --data-urlencode "action=get_vod_info" --data-urlencode "vod_id={}" -o "vi/{}.json" 2>/dev/null' < vi/ids.txt; perl -MJSON::PP -e 'my $J = JSON::PP->new->utf8; my %o; for my $f (glob "vi/*.json") { my ($id) = $f =~ m{vi/(\d+)\.json$} or next; open my $h, "<:raw", $f or next; local $/; my $d = eval { $J->decode(<$h>) } or next; my $i = $d->{info}; next unless ref $i eq "HASH"; my $bd = $i->{backdrop_path}; $bd = $bd->[0] if ref $bd eq "ARRAY"; $o{$id} = { p => substr($i->{plot} // $i->{description} // "", 0, 500), cast => substr($i->{cast} // $i->{actors} // "", 0, 200), dir => substr($i->{director} // "", 0, 80), g => substr($i->{genre} // "", 0, 60), d => int(($i->{duration_secs} // 0) / 60), bd => ($bd // "") =~ m{^https?://} ? $bd : "", tm => (($i->{tmdb_id} // $i->{tmdb} // "") =~ /^\d+$/ ? $i->{tmdb_id} // $i->{tmdb} : ""), yt => $i->{youtube_trailer} // "" } } open my $w, ">:raw", "vod_info.json" or die; print $w $J->canonical->encode(\%o); print STDERR "✓ fiches du fournisseur : " . scalar(keys %o) . " films\n"'; rm -rf vi;
